begin;
create table if not exists public.administrative_regions (
 id text primary key default gen_random_uuid()::text,
 name text not null check(length(trim(name))>0),
 level text not null check(level in ('state','district','subdistrict')),
 parent_id text references public.administrative_regions(id) on delete restrict,
 lgd_code text, country_code text not null default 'IN',
 latitude double precision, longitude double precision,
 is_active boolean not null default true,
 source text not null default 'Eventra Admin', source_date date,
 created_at timestamptz not null default now(),
 unique(level,lgd_code),
 check((latitude is null and longitude is null) or (latitude is not null and longitude is not null and latitude between -90 and 90 and longitude between -180 and 180))
);
create index if not exists administrative_region_parent on public.administrative_regions(parent_id,level,name);
alter table public.administrative_regions enable row level security;
revoke all on public.administrative_regions from anon,authenticated;
grant select on public.administrative_regions to anon,authenticated;
drop policy if exists administrative_regions_read on public.administrative_regions;
create policy administrative_regions_read on public.administrative_regions for select to anon,authenticated using(is_active or public.eventra_is_admin());

alter table public.businesses add column if not exists shop_state_id text references public.administrative_regions(id) on delete restrict;
alter table public.businesses add column if not exists shop_district_id text references public.administrative_regions(id) on delete restrict;
alter table public.businesses add column if not exists shop_subdistrict_id text references public.administrative_regions(id) on delete restrict;
create index if not exists business_shop_subdistrict on public.businesses(shop_subdistrict_id);

create or replace function public.eventra_validate_administrative_region() returns trigger language plpgsql security definer set search_path='' as $$
declare parent public.administrative_regions;
begin
 if new.level='state' and new.parent_id is not null then raise exception 'A state cannot have a parent';end if;
 if new.level<>'state' then
  select * into parent from public.administrative_regions where id=new.parent_id;
  if not found or parent.country_code<>new.country_code or parent.level<>(case when new.level='district' then 'state' else 'district' end) then raise exception 'Select the correct parent state or district';end if;
 end if;
 if tg_op='UPDATE' and (new.level,new.parent_id,new.country_code) is distinct from (old.level,old.parent_id,old.country_code) and (
  exists(select 1 from public.administrative_regions where parent_id=old.id) or
  exists(select 1 from public.businesses where old.id in (shop_state_id,shop_district_id,shop_subdistrict_id))
 ) then raise exception 'This region is in use. Its hierarchy cannot be changed.';end if;
 return new;
end $$;
drop trigger if exists eventra_validate_administrative_region on public.administrative_regions;
create trigger eventra_validate_administrative_region before insert or update on public.administrative_regions for each row execute function public.eventra_validate_administrative_region();

